#include <iostream>
#include <vector>
#include <utility>
using namespace std;

vector<int> a;

void quickSort(int l, int r) {
    int mid = a[l + (r - l) / 2];
    int i = l, j = r;

    while (i <= j) {
        while (a[i] < mid) ++i;
        while (a[j] > mid) --j;
        if (i <= j) {
            swap(a[i], a[j]);
            ++i;
            --j;
        }
    }

    if (l < j) quickSort(l, j);
    if (i < r) quickSort(i, r);
}

int main() {
    int n;
    cin >> n;

    a.resize(n + 1);
    for (int i = 1; i <= n; ++i) cin >> a[i];

    if (n > 0) {
        quickSort(1, n);
        cout << a[(n + 1) / 2];
    }

    return 0;
}

